// The generated bindings live beside this worker on both hosts.
// @ts-expect-error generated by wasm-bindgen before the production build
import init, { run } from "./unknown_browser.js";
let ready: Promise<unknown> | undefined;
self.onmessage = async (event: MessageEvent) => {
  const started = performance.now();
  try {
    ready ??= init();
    await ready;
    const result = JSON.parse(run(JSON.stringify(event.data)));
    self.postMessage({ ...result, durationMs: performance.now() - started });
  } catch (error) {
    self.postMessage({
      stdout: "",
      stderr: error instanceof Error ? error.message : String(error),
      diagnostics: [],
      exitCode: 1,
      durationMs: performance.now() - started,
      files: event.data.files,
      cwd: event.data.cwd,
    });
  }
};
